source(file.path(commandArgs(TRUE)[1],'code/plot_common.R'))
d<-fread(file.path(out,'analysis_metadata.tsv.gz'));m<-fread(file.path(out,'metadata.tsv.gz'));stopifnot(identical(d$bin_id,m$bin_id));for(k in setdiff(names(m),names(d)))d[[k]]<-m[[k]]
regcols<-c('Epithelial-enriched'='#f5b264','Mesenchymal-enriched'='#8b78b8','Immune-enriched'='#57c1b5','Mesenchymal-immune composite region'='#519389','Endothelial-enriched'='#2878b5','Epithelial-mesenchymal mixed signal'='#b64f81','Epithelial-stromal composite region'='#bd907a','Low-information / unresolved'='#d5d5d5','Unresolved expression region'='#7b7b7b','Epithelial-associated (sparse support)'='#f8d6ac','Mesenchymal-associated (sparse support)'='#c2b9db','Immune-associated (sparse support)'='#9cd8d1','Endothelial-associated (sparse support)'='#87b5db')
all<-fread(file.path(out,'bin_metadata.tsv.gz'));v<-rbindlist(list(all[,.(x_um,y_um,value=log10(1+nCount_RNA),metric='log10(1+nCount)')],all[,.(x_um,y_um,value=log10(1+nFeature_RNA),metric='log10(1+nFeature)')]));p<-spfinish(ggplot(v,aes(x_um,-y_um,color=value))+geom_point_rast(size=.08,raster.dpi=300)+facet_wrap(~metric,nrow=1)+scale_color_viridis_c(name='Supplied-bin\ninformation'));export(p,'input_information_all_supplied',13,7,11)
all[,state:=fifelse(qc_keep,'Expression QC kept',qc_reason)];p<-spfinish(ggplot(all,aes(x_um,-y_um,color=state))+geom_point_rast(size=.08,raster.dpi=300)+scale_color_manual(values=c('Expression QC kept'='#57c1b5',nCount_le5='#bdbdbd',outside_original_tissue='#f5b264'),name=if(grepl('MPBC',s))'Input/QC (tissue unknown)' else 'Input/QC'));export(p,'input_QC_coverage',10,7,8)
if(grepl('MPBC',s)){p<-spfinish(ggplot(all,aes(x_um,-y_um,color=supplied_2um_n))+geom_point_rast(size=.08,raster.dpi=300)+scale_color_viridis_c(limits=c(1,16),name='Supplied 2um bins\n(nominal 4x4)'));export(p,'input_supplied_2um_coverage',10,7,8)}
typ<-rbindlist(lapply(c('blca','hpca'),function(k)d[,.(x_um,y_um,candidate=get(paste0('coarse_',k)),reference=toupper(k))]));p<-spfinish(ggplot(typ,aes(x_um,-y_um,color=candidate))+geom_point_rast(size=.09,raster.dpi=300)+facet_wrap(~reference,nrow=1)+scale_color_manual(values=coarse,name='Coarse candidate')+guides(color=guide_legend(override.aes=list(size=3))));export(p,'spatial_coarse_references',14,7,12)
pals<-list()
for(tag in c('l00','l02','l08')){k<-paste0('banksy_',tag,'_cluster');d[[k]]<-as.character(d[[k]]);lev<-as.character(sort(as.integer(unique(d[[k]]))));pa<-setNames(hcl.colors(length(lev),'Dynamic'),lev);pals[[tag]]<-pa;p<-spfinish(ggplot(d,aes(x_um,-y_um,color=.data[[k]]))+geom_point_rast(size=.09,raster.dpi=300)+scale_color_manual(values=pa,name=paste(tag,'cluster'))+guides(color=guide_legend(ncol=8,override.aes=list(size=2))))+theme(legend.position='bottom',legend.key.height=grid::unit(.25,'cm'));export(p,paste0('spatial_clusters_',tag),8,8+ceiling(length(lev)/8)*.23)
 if(tag=='l02'){e<-readRDS(file.path(out,paste0(tag,'_embeddings.rds')))$umap;stopifnot(identical(rownames(e),d$bin_id));v<-data.table(U1=e[,1],U2=e[,2],cluster=d[[k]]);p<-ggplot(v,aes(U1,U2,color=cluster))+geom_point_rast(size=.06,raster.dpi=300)+coord_fixed()+scale_color_manual(values=pa,name=paste(tag,'cluster'))+guides(color=guide_legend(ncol=8,override.aes=list(size=2)))+jin_theme()+theme(legend.position='bottom')+labs(x='UMAP1',y='UMAP2');export(p,'umap_l02',8,8+ceiling(length(lev)/8)*.23)}}
v<-rbindlist(lapply(c('l00','l02','l08'),function(t)d[,.(x_um,y_um,region=get(paste0('banksy_',t,'_region')),branch=t)]));p<-spfinish(ggplot(v,aes(x_um,-y_um,color=region))+geom_point_rast(size=.08,raster.dpi=300)+facet_wrap(~branch,nrow=1)+scale_color_manual(values=regcols,labels=function(x)vapply(x,function(z)paste(strwrap(z,width=28),collapse='\n'),character(1)),name='Region interpretation')+guides(color=guide_legend(override.aes=list(size=3))));export(p,'spatial_interpreted_three_lambda',18,7,14)
# Both candidate spatial branches retained until manual evidence review selects the recommendation.
if(s=='UC_SCC'){tr<-read_json(file.path(out,'transform.json'),simplifyVector=TRUE);bg<-png::readPNG(file.path(out,tr$hires_path));pixel_um<-tr$microns_per_pixel/tr$scalefactors$tissue_hires_scalef;xl<-c(0,ncol(bg)*pixel_um);yl<-c(-nrow(bg)*pixel_um,0);p<-spfinish(ggplot(v[branch=='l08'],aes(x_um,-y_um))+annotation_raster(bg,xl[1],xl[2],yl[1],yl[2])+geom_point_rast(aes(color=region),alpha=.22,size=.055,raster.dpi=300)+scale_color_manual(values=regcols,labels=function(x)vapply(x,function(z)paste(strwrap(z,width=28),collapse='\n'),character(1)),name='Region interpretation'));export(p,'spatial_l08_regions_hires',11,8,8);rm(bg)}
ro<-fread(file.path(out,'fixed_rois.tsv'))
for(i in seq_len(nrow(ro))){b<-ro[i];z<-d[x_um>=b$x&x_um<b$X&y_um>=b$y&y_um<b$Y];v<-rbindlist(lapply(c('blca','hpca'),function(k)z[,.(x_um,y_um,candidate=get(paste0('coarse_',k)),reference=toupper(k))]));p<-spfinish(ggplot(v,aes(x_um,-y_um,color=candidate))+geom_point(size=.9)+facet_wrap(~reference,nrow=1)+scale_color_manual(values=coarse,name='Coarse candidate'));p<-roi_fixed(p,b);export(p,paste0('ROI_candidates_',b$roi),11,5,9)
 v<-rbindlist(lapply(c('l00','l02','l08'),function(t)z[,.(x_um,y_um,label=paste(t,get(paste0('banksy_',t,'_cluster')),sep=':'),branch=t)]));pa<-unlist(lapply(names(pals),function(t)setNames(pals[[t]],paste(t,names(pals[[t]]),sep=':'))),use.names=TRUE);p<-spfinish(ggplot(v,aes(x_um,-y_um,color=label))+geom_point(size=.9)+facet_wrap(~branch,nrow=1)+scale_color_manual(values=pa,name='Branch:cluster')+guides(color=guide_legend(ncol=8,override.aes=list(size=2))))+theme(legend.position='bottom');p<-roi_fixed(p,b);export(p,paste0('ROI_clusters_',b$roi),14,6+ceiling(length(unique(v$label))/8)*.3)
}
mk<-fread(file.path(out,'panel_marker_statistics.tsv.gz'));su<-fread(file.path(out,'cluster_summary.tsv'));largest<-su[branch=='l02'][order(-n)][seq_len(min(.N,25)),as.character(cluster)];genes<-c('EPCAM','KRT7','KRT19','UPK2','COL1A1','COL1A2','DCN','LUM','CD3D','NKG7','LST1','CD68','MS4A1','CD79A','JCHAIN','MZB1','TPSAB1','PECAM1','VWF','RGS5','MYH11');v<-mk[branch=='l02'&as.character(cluster)%in%largest&symbol%in%genes];v[,symbol:=factor(symbol,levels=genes)];p<-ggplot(v,aes(symbol,factor(cluster),size=pct_positive*100,color=mean_log))+geom_point()+scale_size_area(max_size=4,limits=c(0,100),name='Detected (%)')+scale_color_viridis_c(name='Original mean\nLogNormalize')+jin_theme()+theme(axis.text.x=element_text(angle=60,hjust=1))+labs(x=NULL,y='lambda 0.2 cluster (largest 25)');export(p,'markers_l02',13,9,11)
p<-ggplot(su,aes(nFeature_median,edge16_fraction,size=n,color=epi_fib_ge2_fraction))+geom_point()+facet_wrap(~branch,nrow=1)+scale_x_log10()+scale_color_viridis_c(name='Original dual-panel\ndetection fraction')+scale_size_area(max_size=9,name='Bins')+jin_theme()+labs(x='Cluster median nFeature',y='Fraction near input boundary (<=16um)');export(p,'cluster_information_boundary',14,5,12)
